  'LAGE VOORRAAD': { fr: 'STOCK FAIBLE', en: 'LOW STOCK', de: 'NIEDRIGER BESTAND' },
  'Materiaal op deze werkplek heeft het ingestelde minimum bereikt.': { fr: 'Le matériel de ce poste a atteint le minimum configuré.', en: 'Material at this workplace has reached the configured minimum.', de: 'Material an diesem Arbeitsplatz hat den eingestellten Mindestbestand erreicht.' },
  'CHECKLIST OPEN': { fr: 'CHECK-LIST OUVERTE', en: 'CHECKLIST OPEN', de: 'CHECKLISTE OFFEN' },
  'Een operationele checklist is na het geplande moment nog niet afgerond.': { fr: 'Une check-list opérationnelle n’est toujours pas terminée après l’heure prévue.', en: 'An operational checklist is still incomplete after its scheduled time.', de: 'Eine betriebliche Checkliste ist nach dem geplanten Zeitpunkt noch nicht abgeschlossen.' },
  'Open juiste onderdeel': { fr: 'Ouvrir la bonne section', en: 'Open relevant section', de: 'Passenden Bereich öffnen' },
  'Context': { fr: 'Contexte', en: 'Context', de: 'Kontext' },
